    return new_shape

  def normalize(shape):
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    return [(r - min_r, c - min_c) for r, c in shape]

  shapes = []
  for i in range(3):
    shape = get_shape(p[i])
    all_rotations = []
    for _ in range(4):
      shape = rotate(shape)
      norm_shape = normalize(shape)
      if norm_shape not in all_rotations:
        all_rotations.append(norm_shape)
    shapes.append(all_rotations)

  def check_placement(grid, shape, r_offset, c_offset, polyomino_id):
