import heapq

def solve():
    n, m = map(int, input().split())
    trains = []
    for _ in range(m):
        l, d, k, c, a, b = map(int, input().split())
        trains.append((l, d, k, c, a, b))

    def find_latest_arrival(start_node):
        latest_arrivals = {node: -float('inf') for node in range(1, n + 1)}
        latest_arrivals[start_node] = 0

        pq = [(-0, start_node)] 

        while pq:
            time, current_node = heapq.heappop(pq)
            time = -time

            if time < latest_arrivals[current_node]:
                continue

            for l, d, k, c, a, b in trains:
                if a == current_node:
                    for i in range(k):
                        departure_time = l + i * d
                        if departure_time >= time:
                            arrival_time = departure_time + c
                            if arrival_time > latest_arrivals[b]:
                                latest_arrivals[b] = arrival_time
                                heapq.heappush(pq, (-arrival_time, b))

        if latest_arrivals[n] == -float('inf'):
            return -float('inf')
        else:
            return latest_arrivals[n]

    for start_node in range(1, n):
        result = find_latest_arrival(start_node)
        if result == -float('inf'):
            print("Unreachable")
        else:
            print(result)

