                start_row, start_col = r, c
            elif grid[r][c] == 'T':
                goal_row, goal_col = r, c

    def bfs():
        q = [(start_row, start_col, 0, [])]  # row, col, energy, used_medicines
        visited = set()
        visited.add((start_row, start_col, 0, tuple()))

        while q:
            row, col, energy, used_medicines = q.pop(0)

            if row == goal_row and col == goal_col:
                return True

            # Use medicine
            for i in range(N):
                r, c, e = medicines[i]
                if row == r and col == c and i not in used_medicines:
                    new_energy = e
                    new_used_medicines = used_medicines + [i]
                    new_state = (row, col, new_energy, tuple(sorted(new_used_medicines)))
                    if new_state not in visited:
                        visited.add(new_state)
                        q.append((row, col, new_energy, new_used_medicines))

            # Move
            if energy > 0:
                # Up
                if row > 0 and grid[row - 1][col] != '#':
