    A = list(map(int, input().split()))

    MOD = 998244353

    total_outcomes = 1
    for a in A:
        total_outcomes = (total_outcomes * a) % MOD


    def check_sum_10(results):
        for i in range(1 << N):
            subset_sum = 0
            for j in range(N):
                if (i >> j) & 1:
                    subset_sum += results[j]
            if subset_sum == 10:
                return True
        return False


    successful_outcomes = 0

    def generate_outcomes(index, current_results):
        nonlocal successful_outcomes

        if index == N:
            if check_sum_10(current_results):
                successful_outcomes = (successful_outcomes + 1) % MOD
            return

        for i in range(1, A[index] + 1):
            generate_outcomes(index + 1, current_results + [i])

    generate_outcomes(0, [])


    def mod_inverse(a, m):
        m0 = m
        y = 0
        x = 1

        if m == 1:
            return 0

        while a > 1:
            q = a // m
            t = m
            m = a % m
            a = t
            t = y
            y = x - q * y
            x = t

        if x < 0:
            x = x + m0

        return x


    probability = (successful_outcomes * mod_inverse(total_outcomes, MOD)) % MOD

    print(probability)

