def solve():
    def power_sum(n, x, num=1, memo={}):
        if (n, num) in memo:
            return memo[(n, num)]

        if n == 0:
            return 1

        if n < 0:
            return 0

        power = num ** x

        if power > n:
            return 0

        ans = (power_sum(n - power, x, num + 1, memo) + power_sum(n, x, num + 1, memo)) % (10**9 + 7)
        memo[(n, num)] = ans
        return ans

    return power_sum(n, x)
