            return True
        if board[0][2] == color and board[1][1] == color and board[2][0] == color:
            return True
        return False

    def get_winner(board, scores):
        if check_win(board, 'R'):
            return "Takahashi"
        if check_win(board, 'B'):
            return "Aoki"

        white_cells = 0
        for i in range(3):
            for j in range(3):
                if board[i][j] == 'W':
                    white_cells += 1

        if white_cells == 0:
            if scores['R'] > scores['B']:
                return "Takahashi"
            else:
                return "Aoki"

        return None  # Game not over

    def minimax(board, scores, maximizing_player):

      winner = get_winner(board,scores)
      if winner:
        if winner == "Takahashi":
          return 1
        elif winner == "Aoki":
          return -1
        else:
          if scores["R"] > scores["B"]:
            return 1
          else:
            return -1

      if maximizing_player:
        max_eval = -float('inf')
        for i in range(3):
          for j in range(3):
            if board[i][j] == 'W':
              new_board = [row[:] for row in board]
              new_board[i][j] = 'R'
              new_scores = scores.copy()
              new_scores['R'] += a[i][j]
              eval = minimax(new_board, new_scores, False)
              max_eval = max(max_eval, eval)
        return max_eval
      else:
        min_eval = float('inf')
        for i in range(3):
          for j in range(3):
            if board[i][j] == 'W':
              new_board = [row[:] for row in board]
              new_board[i][j] = 'B'
              new_scores = scores.copy()
              new_scores['B'] += a[i][j]
              eval = minimax(new_board, new_scores, True)
              min_eval = min(min_eval, eval)
        return min_eval


    initial_board = [['W'] * 3 for _ in range(3)]
    initial_scores = {'R': 0, 'B': 0}

    result = minimax(initial_board, initial_scores, True)

    if result > 0:
        print("Takahashi")
