def continuousSubarrays(nums):
    """
    Given a 0-indexed integer array nums. A subarray of nums is called continuous if:

    Let i, i + 1, ..., j_ be the indices in the subarray. Then, for each pair of indices i <= i_1, i_2 <= j, 0 <= |nums[i_1] - nums[i_2]| <= 2.

    Return the total number of continuous subarrays.
    """
    n = len(nums)
    count = 0
    for i in range(n):
        for j in range(i, n):
            subarray = nums[i:j+1]
            is_continuous = True
            for k in range(len(subarray)):
                for l in range(k + 1, len(subarray)):
                    if abs(subarray[k] - subarray[l]) > 2:
                        is_continuous = False
                        break
                if not is_continuous:
                    break
            if is_continuous:
                count += 1
    return count
