def solve():
  n = int(input())
  edges = []
  for _ in range(n - 1):
    u, v = map(int, input().split())
    edges.append((u, v))

  def get_neighbors(node, current_edges):
    neighbors = []
    for u, v in current_edges:
      if u == node:
        neighbors.append(v)
      elif v == node:
        neighbors.append(u)
    return neighbors

  def is_leaf(node, current_edges):
    return len(get_neighbors(node, current_edges)) <= 1

  def remove_leaf(leaf_node, current_edges):
    new_edges = []
    for u, v in current_edges:
      if u != leaf_node and v != leaf_node:
        new_edges.append((u, v))
    return new_edges

  def can_remove_node_1(edges):
      node_1_present = False
      for u,v in edges:
          if u == 1 or v == 1:
              node_1_present = True
              break

      return not node_1_present


  def find_min_operations(edges, n):
    q = [(edges, 0)]
    visited = {tuple(sorted(edges)): 0}

    while q:
      current_edges, steps = q.pop(0)
      if can_remove_node_1(current_edges):
        return steps

      leaves = []
      for i in range(1, n + 1):
          is_present = False
          for u,v in current_edges:
              if u == i or v == i:
                  is_present = True
                  break
          if is_present and is_leaf(i, current_edges):
            leaves.append(i)

      for leaf in leaves:
          new_edges = remove_leaf(leaf, current_edges)
          new_edges_tuple = tuple(sorted(new_edges))
          if new_edges_tuple not in visited:
            q.append((new_edges, steps + 1))
            visited[new_edges_tuple] = steps+1

    return float('inf')

  result = find_min_operations(edges, n)
  print(result)

solve()
