                sub1_counts = Counter(sub1)
                sub2_counts = Counter(sub2)


                temp_s = list(s_list)

                import itertools


                def backtrack(index, current_s):
                    if index == n // 2:

                        if check_palindrome(current_s):
                            return True
                        else:
                            return False

                    if a <= index <= b:

                        for perm in itertools.permutations(sub1):
                            temp_sub1 = list(perm)

                            temp_s2 = list(current_s)
                            for i in range(a, b + 1):
                                temp_s2[i] = temp_sub1[i - a]


                            c_index = n - 1 - index
                            if c <= c_index <= d:
                                for perm2 in itertools.permutations(sub2):
                                    temp_sub2 = list(perm2)

                                    temp_s3 = list(temp_s2)

                                    for j in range(c, d + 1):
                                        temp_s3[j] = temp_sub2[j - c]


                                    if check_palindrome(temp_s3):
                                        return True


                            else:
                                if check_palindrome(temp_s2):
                                    return True


                        return False
                    else:

                        c_index = n - 1 - index
                        if c <= c_index <= d:
                            for perm2 in itertools.permutations(sub2):
                                temp_sub2 = list(perm2)

                                temp_s3 = list(current_s)

                                for j in range(c, d + 1):
                                    temp_s3[j] = temp_sub2[j - c]


                                if check_palindrome(temp_s3):
                                    return True

                            return False
                        else:
                            new_s = list(current_s)


                            if backtrack(index+1, new_s):
                                return True
                            else:
                                return False


                return backtrack(0, s_list)

            ans.append(solve_query(s1, a, b, c, d))
