def canMakeZeros(nums, k):
    n = len(nums)
    diff = [0] * n
    curr = 0
    for i in range(n):
        curr += diff[i]
        nums[i] -= curr
        if nums[i] < 0:
            return False
        if nums[i] > 0:
            if i + k > n:
                return False
            diff[i] += nums[i]
            if i + k < n:
                diff[i + k] -= nums[i]
    return all(x == 0 for x in nums)
