        q = [(start_r, start_c, 0)]
        visited = set()
        visited.add((start_r, start_c))

        while q:
            r, c, d = q.pop(0)

            if r == end_r and c == end_c:
                return d

            neighbors = [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]

            for nr, nc in neighbors:
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and (nr, nc) not in visited:
                    q.append((nr, nc, d + 1))
                    visited.add((nr, nc))
        return float('inf')

    dist[(start_row, start_col)] = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != '#':
                distance = bfs(start_row, start_col, r, c)
                if distance != float('inf'):
                    dist[(start_row, start_col)][(r, c)] = distance


    for i in range(num_candies):
