    total_length = sum(len(word) for word in words)
    palindrome_count = 0

    for word in words:
        if len(word) % 2 == 0:
            if odd_counts > 0:
                if len(word) // 2 <= odd_counts // 2:
                    odd_counts -= len(word)
                    palindrome_count += 1
                else:
                    break
            else:
