import heapq

def solve():
    n, a, b, c = map(int, input().split())
    d = []
    for _ in range(n):
        d.append(list(map(int, input().split())))

    def dijkstra(start_node):
        dist_car = [float('inf')] * n
        dist_train = [float('inf')] * n
        dist_car[start_node] = 0
        dist_train[start_node] = float('inf')  # Initially, no train travel allowed

        pq_car = [(0, start_node)]  # (distance, node)
        pq_train = []

        while pq_car or pq_train:
            if pq_car and (not pq_train or pq_car[0][0] <= pq_train[0][0]):
                dist, u = heapq.heappop(pq_car)

                if dist > dist_car[u]:
                    continue

                # Explore neighbors with car
                for v in range(n):
                    if u != v:
                        weight = d[u][v] * a
                        if dist_car[u] + weight < dist_car[v]:
                            dist_car[v] = dist_car[u] + weight
                            heapq.heappush(pq_car, (dist_car[v], v))

                        # Check switching to train here
                        if dist_car[u] < dist_train[u]:
                            dist_train[u] = dist_car[u]

                        if dist_car[u] < dist_train[u]:
                             dist_train[u] = dist_car[u]

            elif pq_train:
