                            heapq.heappush(pq_train, (dist_train[v], v))


            # Update train distances from car distances (switching)
            for u in range(n):
                if dist_car[u] < dist_train[u]:
                   dist_train[u] = dist_car[u]


            for u in range(n):
                if dist_train[u] != float('inf'):
