def minCostToConvert(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    """
    Given two 0-indexed strings source and target, both of length n and consisting of lowercase English letters.
    You are also given two 0-indexed character arrays original and changed, and an integer array cost,
    where cost[i] represents the cost of changing the character original[i] to the character changed[i].

    You start with the string source. In one operation, you can pick a character x from the string and change it
    to the character y at a cost of z if there exists any index j such that cost[j] == z, original[j] == x,
    and changed[j] == y.

    Return the minimum cost to convert the string source to the string target using any number of operations.
    If it is impossible to convert source to target, return -1.

    Note that there may exist indices i, j such that original[j] == original[i] and changed[j] == changed[i].
    """

    n = len(source)
    adj = {}
    for i in range(26):
        adj[chr(ord('a') + i)] = {}

    for i in range(len(original)):
        adj[original[i]].setdefault(changed[i], float('inf'))
        adj[original[i]][changed[i]] = min(adj[original[i]][changed[i]], cost[i])

    for k in range(26):
        k_char = chr(ord('a') + k)
        for i in range(26):
            i_char = chr(ord('a') + i)
            for j in range(26):
                j_char = chr(ord('a') + j)

                if i_char in adj and k_char in adj[i_char] and j_char in adj and k_char in adj and j_char in adj[k_char]:
                   adj[i_char].setdefault(j_char, float('inf'))
                   adj[i_char][j_char] = min(adj[i_char][j_char], adj[i_char][k_char] + adj[k_char][j_char])
                elif i_char in adj and k_char in adj[i_char] and k_char in adj and j_char in adj[k_char]:
                    adj[i_char].setdefault(j_char, float('inf'))
                    adj[i_char][j_char] = min(adj[i_char][j_char], adj[i_char][k_char] + adj[k_char][j_char])

    total_cost = 0
    for i in range(n):
        if source[i] != target[i]:
            if source[i] not in adj or target[i] not in adj[source[i]]:
                return -1
            else:
                total_cost += adj[source[i]][target[i]]

    return total_cost
