def completeSubstrings(word: str, k: int) -> int:
    n = len(word)
    count = 0
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            sub = word[i:i + length]

            # Check if the absolute difference between adjacent characters is at most 2
            valid_adjacent = True
            for j in range(len(sub) - 1):
                if abs(ord(sub[j]) - ord(sub[j+1])) > 2:
                    valid_adjacent = False
                    break

            if not valid_adjacent:
                continue

            # Check if each character occurs exactly k times
            char_counts = {}
            for char in sub:
                char_counts[char] = char_counts.get(char, 0) + 1

            valid_counts = True
            for char in char_counts:
                if char_counts[char] != k:
                    valid_counts = False
                    break

            if valid_counts and len(char_counts) > 0:
                count += 1

    return count
