    for i in range(n - 1):
        for j in range(i + 1, n):
            length = j - i + 1
            if length > 1:
                is_alternating = True
                if nums[i + 1] - nums[i] != 1:
                    is_alternating = False
                else:
                    for k in range(i + 2, j + 1):
