def shortestSubarray(nums, target):
    n = len(nums)
    total_sum = sum(nums)
    if total_sum == 0:
        if target == 0:
            return 1
        else:
            return -1

    if target > 0 and total_sum <= 0:
        return -1
    if target < 0 and total_sum >= 0:
        return -1

    ans = float('inf')

    if target > 0:
        k = target // total_sum
        rem = target % total_sum

        if rem == 0:
            ans = min(ans, k * n)
        else:

            curr_sum = 0
            left = 0

            for right in range(2 * n):
                curr_sum += nums[right % n]

                while curr_sum > rem:
                    curr_sum -= nums[left % n]
                    left += 1

                if curr_sum == rem:
                    ans = min(ans, (k * n) + (right - left + 1))
    else: 
        k = target // total_sum
        rem = target % total_sum

        if rem == 0:
            ans = min(ans, k * n)
        else:

            curr_sum = 0
            left = 0

            for right in range(2 * n):
                curr_sum += nums[right % n]

                while curr_sum < rem:
                    curr_sum -= nums[left % n]
                    left += 1

                if curr_sum == rem:
                    ans = min(ans, (k * n) + (right - left + 1))


    if ans == float('inf'):
        return -1
    else:
        return ans
