def minGroupsForValidAssignment(nums: list[int]) -> int:
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    freqs = list(counts.values())
    freqs.sort()

    def check(group_size):
        groups = 0
        for freq in freqs:
            num_groups = freq // (group_size + 1)
            rem = freq % (group_size + 1)

            if rem > group_size:
                return float('inf')

            if rem > 0:
                num_groups += 1

            groups += num_groups

        return groups

    ans = float('inf')
    for group_size in range(1, max(freqs) + 1):
        ans = min(ans, check(group_size))

    return ans
