def longestSubsequence(nums, target):
    n = len(nums)
    dp = {}

    def solve(index, current_sum):
        if index == n:
            if current_sum == target:
                return 0
            else:
                return float('-inf')

        if (index, current_sum) in dp:
            return dp[(index, current_sum)]

        # Option 1: Exclude the current element
        exclude = solve(index + 1, current_sum)

        # Option 2: Include the current element
        include = float('-inf')
        if current_sum + nums[index] <= target:
            include = 1 + solve(index + 1, current_sum + nums[index])

        dp[(index, current_sum)] = max(exclude, include)
        return dp[(index, current_sum)]

    result = solve(0, 0)
    if result == float('-inf'):
        return -1
    else:
        return result
